tool_input.command:
(PORT=5199 npm run dev >/tmp/dev.log 2>&1 & echo $! >/tmp/dev.pid); sleep 3; PORT=5199 node scripts/screenshots.ts; cat > /tmp/touch.mjs <<'EOF'
import { chromium, devices } from "/Users/alitahseen/Demos/chess-test.wt/r1-C/node_modules/@playwright/test/index.mjs";
const b = await chromium.launch();
const ctx = await b.newContext({ ...devices["iPhone 13"] });
const p = await ctx.newPage();
const errs=[]; p.on("console",m=>{if(m.type()==="error")errs.push(m.text())}); p.on("pageerror",e=>errs.push(String(e)));
await p.goto("http://localhost:5199/");
await p.waitForSelector("[data-square]");
const a = await p.locator('[data-square="e2"]').boundingBox(), t = await p.locator('[data-square="e4"]').boundingBox();
const c = await ctx.newCDPSession(p);
const pt=(b)=>({x:b.x+b.width/2,y:b.y+b.height/2});
await c.send("Input.dispatchTouchEvent",{type:"touchStart",touchPoints:[pt(a)]});
await c.send("Input.dispatchTouchEvent",{type:"touchMove",touchPoints:[pt(t)]});
await c.send("Input.dispatchTouchEvent",{type:"touchEnd",touchPoints:[]});
console.log("e4 piece:", await p.locator('[data-square="e4"] [data-piece]').getAttribute("data-piece"), errs);
await b.close();
EOF
node /tmp/touch.mjs
